import { join } from "path";

export interface AppConfig {
  /** 고객 알림 토픽 */
  topic: string;
  /** 사내 메시지 키 네임스페이스 */
  keyNamespace: string;
  /** mqpub 실행 파일 경로 */
  mqpubBin: string;
