import { createHash } from "crypto";
import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 알림 메시지 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`에 해시 마디를 끼운다.
 *  - mqpub 3.x는 한 배치 안에서 키 앞 16바이트가 같은 메시지를 중복으로 보고 첫 것만 남긴다.
 *    같은 날 같은 채널의 주문은 앞부분(`ntf.ship.O261007`)이 모두 같으므로, 해시를 앞에 둬서 구별한다.
 *  - 해시는 논리 키의 결정적 값이라 같은 알림은 늘 같은 키다(소비 측 중복 방지 유지).
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${KIND_CODE[kind]}.${orderNo}`;
  const tag = createHash("sha1").update(`${namespace}.${logical}`).digest("hex").slice(0, 12);
  return `${namespace}.${tag}.${logical}`;
}

